from author import C,S,P,V
c=C('线性相关与矩阵的秩')
S(c,'什么时候存在重复的信息',[
 P('如果一组向量里，有一个能够由其余向量组合出来，就出现了可以替代的信息。更统一的说法是，能够找到不全为零的一组系数，让这些向量的线性组合等于零，就叫线性相关。强调的是系数不全为零；所有系数都取零当然总能得到零，那不能说明方向发生了重复。',V('vectors',u=[1,1],v=[2,2],phase='cancel'),[r'c_1\mathbf{a}_1+\cdots+c_s\mathbf{a}_s=0',r'(c_1,\ldots,c_s)\ne0'],['相关：存在不全为零的系数','零向量必使所在向量组相关'],10),
 P('如果只有系数全为零才能凑成零，就叫线性无关。图上两支不共线的平面箭头，想让它们完全抵消，两个系数只能都为零。常见结论也可以从活动范围理解：无关组的子组仍无关，相关组增加向量后仍相关；n 维里超过 n 个向量一定相关。相关组的某个子组却可能无关，不要把这些方向关系反着套用。',V('vectors',u=[1,0],v=[0,1],phase='independent'),[r'\sum_i c_i\mathbf{a}_i=0\Rightarrow c_i=0',r's>n\Rightarrow\text{相关}'],['无关：没有可替代的方向','结论有明确的子组与扩充方向'],10)],['3.2-定义与判断','3.2-相关无关定理及推论'])
S(c,'秩把独立信息数出来',[
 P('从一组向量里尽量挑出线性无关的向量，直到再加入任何一个剩余向量都会相关，得到一个极大无关组。这里的极大表示不能继续加，不是要求找长度最大的箭头。极大无关组可能有不同选法，但包含的向量数相同，这个数叫向量组的秩。其他向量都能由选出来的这些向量表示。',V('rank',A=[[1,2,0],[0,0,1]],phase='columns'),[r'r(\mathbf{a}_1,\ldots,\mathbf{a}_s)=2'],['尽量保留不能被替代的向量','选法可以不同，个数相同'],10),
 P('对矩阵，列向量组的秩、行向量组的秩相同，都叫矩阵的秩。另一种等价定义，是找出非零子式的最高阶数。子式指选若干行、若干列形成的小方阵的行列式。二行三列的矩阵，秩最多二；一般 m 行 n 列时不超过二者较小值。零矩阵的秩为零，达到行数叫行满秩，达到列数叫列满秩，要看讨论的是哪一边。',V('rank',A=[[1,2,0],[0,0,1]],phase='minor'),[r'r(A)=\text{最高阶非零子式的阶数}',r'0\le r(A)\le\min(m,n)'],['行秩与列秩相等','满行秩与满列秩要区分'],8)],['2.5-秩定义与范围满秩','3.3-极大无关组与秩'])
S(c,'消元后怎样找极大无关组',[
 P('把矩阵做行变换，化成阶梯形。每个非零行第一个关键位置叫主元位置，它们从上往下向右错开。阶梯形里非零行的数量，就是矩阵的秩。这里第二行减第一行的两倍，只剩一行独立信息，因此秩是一。不能直接数原矩阵有几行非零，因为原来非零的行仍可能互相重复。',V('elimination',states=[[[1,2,3],[2,4,6]],[[1,2,3],[0,0,0]]],labels=['原矩阵','R₂ ← R₂ − 2R₁']),[r'r(A)=\text{阶梯形非零行数}=1'],['先化阶梯形，再数非零行','原来的非零行不一定独立'],10),
 P('想找原列向量组的极大无关组，先在阶梯形里认出主元列的编号，再回到原矩阵选择这些编号对应的列。这里第一列就是一个可选的极大无关组，后两列分别是它的两倍、三倍。不要直接把行变换之后的列抄成原向量的答案，因为它们的分量已经改变；保留的是原列之间的线性关系。',V('rank',A=[[1,2,3],[2,4,6]],phase='pivots',pivots=[0]),[r'\mathbf{a}_2=2\mathbf{a}_1',r'\mathbf{a}_3=3\mathbf{a}_1'],['主元列给出编号','最终选的是原矩阵对应列'],10)],['2.5-阶梯形求秩','3.3-求极大无关组'])
S(c,'矩阵等价与等价标准形',[
 P('如果一张矩阵能够经过有限次初等行变换和列变换，变成另一张，就称它们等价。它们有相同尺寸，而且秩相同。通过行和列一起调整，可以把独立部分整理成一个单位块，其他位置全为零，这就是等价标准形。单位块的大小等于秩，因而同样尺寸的矩阵，是否等价最终由秩决定。',V('elimination',states=[[[1,2,0],[0,0,1]],[[1,0,0],[0,1,0]]],labels=['原矩阵，秩二','行列变换后的标准形']),[r'PAQ=[\,I_r,0;0,0\,]',r'r(A)=r(B)\quad\text{同尺寸时判等价}'],['等价允许初等行与列变换','标准形只保留大小为 r 的单位块'],10),
 P('注意，仅做行变换得到的简化阶梯形，未必就是这个只有单位块和零块的标准形；消掉额外列上的系数，可能还需要列变换。等价也不等于矩阵相等，更不等于后面要讲的相似。这里左右分别乘可逆矩阵，保证独立信息数量不变。先把允许做什么操作说清楚，再讨论哪些性质能够保留。',V('rank',A=[[1,2,0],[0,0,1]],phase='canonical'),[r'P,Q\text{分别可逆}',r'r(PAQ)=r(A)'],['仅行变换未必得到等价标准形','等价、相似、合同条件不同'],8)],['2.4-矩阵等价与标准形'])
S(c,'用秩的不等式约束结果',[
 P('两组向量放在一起，合起来的独立方向数，不会少于任意一组，也不会超过两组秩的和。如果两组提供了重合方向，上界就不一定取到。矩阵相加的秩，也不超过两者秩的和；但有可能相互抵消，所以不应随便给它加上一个以两者秩较大值为下界的结论。比如 A 加负 A 就成为零矩阵。',V('vectors',u=[1,0],v=[0,1],phase='span'),[r'\max(rA,rB)\le r[A\ B]\le rA+rB',r'r(A+B)\le r(A)+r(B)'],['拼接和相加是不同运算','相加时可能发生抵消'],10),
 P('相乘时，输出方向数不会超过两个环节中较少的那个，所以乘积的秩不超过两者秩的较小值。还有常见的下界：若中间尺寸为 n，乘积秩至少是两者秩之和减 n。这些不等式能帮助检查一个计算结果有没有超出可能范围。原文件没有给出两个不等式的具体公式，这里把常见的拼接、求和和乘积版本一并列出，避免混淆。',V('transform',A=[[1,0],[0,0]]),[r'r(AB)\le\min(rA,rB)',r'r(AB)\ge r(A)+r(B)-n'],['乘积秩有上界与下界','n 是相乘时的中间尺寸'],10)],['3.3-秩相关定理','3.3-秩不等式'])
S(c,'练习：三列就有三个方向吗',[
 P('矩阵的三列依次是一和二、二和四、三和六。请判断秩是多少，再指出一个极大无关组。你可以观察列之间的倍数，也可以先把第二行减去第一行的两倍。注意矩阵只有两行，秩本来就不可能达到三；但上界是二，不意味着实际一定等于二。请独立思考四秒。',V('matrix',A=[[1,2,3],[2,4,6]],highlight='columns'),[r'r(A)\ ?'],['上界与实际值不是一回事','查看是否存在重复方向'],0)],['3.3-练习'],kind='question',answer='秩为1；任意一列单独构成一个极大无关组。')
S(c,'答案：三列只需保留一列',[
 P('秩是一。第二列是第一列的两倍，第三列是第一列的三倍，所以只需要保留一个非零列方向。第一列单独就构成一个极大无关组。选择第二列或第三列也可以，因为它们同样非零，都能表示其余两列。极大无关组不唯一，但这些选法都只有一个向量，秩是同一个数。',V('rank',A=[[1,2,3],[2,4,6]],phase='pivots',pivots=[0]),[r'r(A)=1'],['非零列只提供一个独立方向','极大无关组可有不同选法'],10),
 P('请回想，刚才同一个事实被我们用三种方式看到：图上三支箭头共线，列之间存在倍数关系，消元以后只有一个非零行。这些角度应当得到一致答案。以后一个结果和图形明显冲突时，不要急着背下一条公式，先检查对象、尺寸和运算过程。现在用秩来讨论，什么时候方程组有解，以及解为什么有时会形成一整条线。',V('vectors',u=[1,2],v=[2,4],phase='span'),[r'\text{几何、列关系、消元相互核对}'],['多个角度应得出相同结论','下一步：用秩判断方程组'],10)],['3.3-练习答案'])

c=C('线性方程组与解的结构')
S(c,'唯一解、无解与无穷多解',[
 P('先把每条二元一次方程画成一条直线。两条线相交，交点同时满足两条方程，因此有唯一解。两条线平行而不重合，没有共同点，就无解。若两条线重合，同一条线上每个点都满足要求，于是有无穷多解。我们只讨论实数范围，所以这里不会把无穷多种情况误称成某个有限的多解数量。',V('equations',mode='cases'),[r'A\mathbf{x}=\mathbf{b}'],['解必须同时满足所有方程','图像可能是交点、空集或整条线'],14),
 P('用矩阵表达，把系数排成 A，未知数排成列向量，常数排成 b。再把 b 接在右边形成增广矩阵。线性方程组有解，当且仅当系数矩阵和增广矩阵的秩相同。相同且等于未知数个数 n，就是唯一解；相同但小于 n，就是无穷多解；两个秩不同则无解。这里 n 是未知数个数，不是方程条数。',V('elimination',states=[[[1,1,3],[2,2,7]],[[1,1,3],[0,0,1]]],labels=['增广矩阵','出现 0 = 1'],split=2),[r'r(A)=r([A\ b])\iff\text{有解}',r'r(A)=n:\text{唯一};\quad r(A)<n:\text{无穷多}'],['先比两种秩，再比未知数个数','矛盾行说明增广列增加了秩'],10)],['4.1-矩阵形式','4.1-齐次非齐次解的判定'])
S(c,'齐次方程组的解为什么经过原点',[
 P('把右边全部换成零，得到齐次方程组。零向量一定是解，所以它绝不会无解。如果两个向量都是解，它们相加后还是解；一个解乘任意实数，也仍是解。这来自矩阵保持加法和数乘，因此解的集合本身构成一个向量空间。入门先看图：它可能只有原点，也可能是过原点的直线或平面。',V('nullspace',mode='homogeneous'),[r'A\mathbf{x}=0',r'A(c_1\mathbf{u}+c_2\mathbf{v})=0'],['零向量总是解','齐次解对加法和数乘封闭'],12),
 P('如果 n 个未知数的系数矩阵秩等于 n，所有未知数都被独立条件确定，只剩零解。秩小于 n，存在自由变量，就会有非零解。对方阵，这和之前行列式是否为零的判断一致；对长方形矩阵，秩仍然能用。请注意，是否非零和是否唯一是两个不同问法；齐次系统唯一时，唯一的就是零向量。',V('rank',A=[[1,1,1],[0,1,1]],phase='pivots',pivots=[0,1]),[r'r(A)=n\iff\text{仅零解}',r'r(A)<n\iff\text{存在非零解}'],['自由变量的个数与 n−r 有关','长方形矩阵也能用秩判断'],8)],['4.1-齐次解判定','4.2-齐次解结构'])
S(c,'从自由变量写出基础解系',[
 P('来看三个未知数的例子。第一条是 x 加 y 加 z 等于零，第二条是 y 加 z 等于零。两条独立约束说明秩是二，未知数有三个，因此剩一个自由变量。让 z 等于 t，由第二条得到 y 等于负 t，代回第一条得到 x 等于零。于是所有解都写成 t 乘零、负一、一组成的向量。',V('nullspace',mode='three',direction=[0,-1,1],particular=[0,0,0]),[r'x+y+z=0,\quad y+z=0',r'\mathbf{x}=t(0,-1,1)^T'],['选自由变量，再解其余变量','不是随便把每个未知数都设成参数'],12),
 P('向量零、负一、一就是这套齐次系统的一组基础解系。基础解系要同时满足两件事：这些解向量线性无关，而且能组合出全部齐次解。如果系数矩阵秩为 r，未知数有 n 个，它包含 n 减 r 个向量。若没有自由变量，解只有零，不是把零向量当成一个基础方向；零向量本身不能构成线性无关组。',V('nullspace',mode='three',direction=[0,-1,1],particular=[0,0,0],phase='basis'),[r'\dim\ker A=n-r(A)',r'\text{本例：}3-2=1'],['基础解系既无关，又能表示全部解','向量个数是 n−r'],10)],['4.2-基础解系与个数','4.2-求基础解系与通解'])
S(c,'非齐次解是平移后的齐次解',[
 P('现在右边不全为零，方程改成 x 加 y 加 z 等于二，y 加 z 等于一。先找到一个特解，例如一、一、零。再加上刚才齐次系统的任意一个解，就得到新的解。图上经过原点的解直线被平移到特解所在位置。它通常不再经过原点，因此非齐次系统的全部解一般不构成向量空间。',V('nullspace',mode='three',direction=[0,-1,1],particular=[1,1,0],phase='translate'),[r'\mathbf{x}=(1,1,0)^T+t(0,-1,1)^T'],['先找一个特解','再加对应齐次系统的全部解'],12),
 P('为什么这就是全部？任意两个非齐次解相减，右边的 b 抵消，差就满足齐次方程。反过来，一个特解加任意齐次解，代入以后仍得到 b。所以非齐次通解等于一个特解加齐次通解。这个说法先要求原方程组有解；若两个秩不同，连特解都找不到，就不能硬写这条结构公式。',V('nullspace',mode='three',direction=[0,-1,1],particular=[1,1,0],phase='difference'),[r'\mathbf{x}=\mathbf{x}_p+\mathbf{x}_h',r'A(\mathbf{x}_1-\mathbf{x}_2)=0'],['两个非齐次解之差是齐次解','先判断有解，再谈通解结构'],10)],['4.3-非齐次解结构与通解'])
S(c,'练习：秩相同就唯一吗',[
 P('一个实数线性方程组有三个未知数。系数矩阵的秩是二，增广矩阵的秩也是二。它无解、唯一解，还是无穷多解？若改成右边全为零的对应齐次系统，基础解系里应该有几个向量？先把判断拆成两步：两个秩是否相同，以及这个秩是否达到未知数个数。',V('rank',A=[[1,1,1],[0,1,1]],phase='question'),[r'n=3,\quad r(A)=r([A\ b])=2'],['先判断有解，再判断自由变量','不要把方程条数当作 n'],0)],['4-练习'],kind='question',answer='无穷多解；对应齐次系统的基础解系含1个向量。')
S(c,'答案：有一个自由方向',[
 P('两个秩相同，说明有解；但秩二小于未知数个数三，所以有一个自由变量，在实数范围内有无穷多解。对应齐次系统的基础解系包含三减二，也就是一个向量。一个向量不是一个解的意思，而是一个基础方向；这个方向的任意实数倍，都给出一份齐次解。',V('nullspace',mode='three',direction=[0,-1,1],particular=[1,1,0],phase='translate'),[r'n-r=1',r'\mathbf{x}=\mathbf{x}_p+t\mathbf{v}'],['有解不等于唯一解','一个基础方向可以产生无穷多解'],12),
 P('以后求通解，可以照这个顺序做：写增广矩阵，消元，检查矛盾行，辨认主元与自由变量，再把参数形式整理成向量形式。齐次时找基础解系，非齐次时再加一个特解。每一步都能回到原方程代入核对。接下来我们不再只问能到哪里，而是寻找一种特别的方向：经过矩阵以后，方向所在的直线仍然不变。',V('equations',mode='coincident'),[r'\text{消元}\to\text{自由变量}\to\text{向量通解}'],['最后代回原方程检查','下一步：寻找特殊不变方向'],6)],['4-练习答案'])
